/**
 * /api/library/tag — 曲目标签的打标控制面。
 *
 * GET                     进度状态：{tagged, total, pending, running, lastError}
 * POST {mode:'bulk', limit?}   大批量模式：处理一批（默认 8 首）没 LLM 标签的歌，
 *                              幂等可续跑 —— 循环调用直到 remaining=0。
 * POST {mode:'lazy', trackId}  边放边标模式：单首塞进串行后台队列（fire-and-forget）。
 *
 * 两种模式的取舍见 RADIO.md §10：bulk 适合刚导入一大批歌；lazy 省 token
 * （只标真正播放过的），由播放钩子自动触发，也可手动点名。
 */
import { bulkBatch, enqueueLazy, taggerStatus } from '@/server/radio/tagger';
import { findSongById } from '@/server/library';
import { ok, fail } from '@/server/http';

export async function GET() {
	return ok(await taggerStatus());
}

export async function POST(request: Request) {
	let body: { mode?: unknown; limit?: unknown; trackId?: unknown };
	try {
		body = await request.json();
	} catch {
		return fail('Invalid JSON body', 400);
	}

	if (body.mode === 'bulk') {
		const limit = typeof body.limit === 'number' ? body.limit : 8;
		const data = await bulkBatch(limit);
		return ok(data);
	}

	if (body.mode === 'lazy') {
		const trackId = typeof body.trackId === 'string' ? body.trackId : '';
		const song = trackId ? await findSongById(trackId) : undefined;
		if (!song) return fail(`track not found: ${trackId}`, 404);
		enqueueLazy(trackId);
		return ok(await taggerStatus());
	}

	return fail("mode must be 'bulk' or 'lazy'", 400);
}
